import test from 'node:test';
import assert from 'node:assert/strict';
import {parseStudyBars,measureEvent} from '../server/event-study.mjs';
import {openStore} from '../server/store.mjs';
import {openResearch} from '../server/research.mjs';
const payload={chart:{result:[{meta:{symbol:'NVO',currency:'USD',exchangeTimezoneName:'America/New_York'},timestamp:[Date.parse('2026-09-21T13:30Z')/1000,Date.parse('2026-09-22T13:30Z')/1000],indicators:{quote:[{close:[100,105]}]}}]}};
test('historical daily study excludes current-market-day partial bars',()=>{const p=parseStudyBars(payload,'NVO.US','1d','2026-09-22T18:00:00Z');assert.equal(p.bars.length,1);assert.equal(p.bars[0].date,'2026-09-21');});
test('study rejects wrong security and wrong currency',()=>{assert.throws(()=>parseStudyBars(payload,'BA.US','1d','2026-09-24T08:00:00Z'));const bad=structuredClone(payload);bad.chart.result[0].meta.currency='HKD';assert.throws(()=>parseStudyBars(bad,'NVO.US','1d','2026-09-24T08:00:00Z'));});
test('study uses next session, retains losses and leaves immature windows null',()=>{const p=parseStudyBars(payload,'NVO.US','1d','2026-09-24T08:00:00Z');p.bars.push({at:'2026-09-23T13:30:00Z',date:'2026-09-23',close:99});const r=measureEvent(p,'2026-09-21');assert.equal(r.anchor.date,'2026-09-22');assert.ok(r.outcomes[0].change<0);assert.equal(r.outcomes[1].change,null);assert.equal(measureEvent(p,'2026-09-24').anchor,null);});
test('corporate action blocks uninterpretable price return',()=>{const p=parseStudyBars(payload,'NVO.US','1d','2026-09-24T08:00:00Z');p.actions={splits:{x:{date:Date.parse('2026-09-22T13:30:00Z')/1000}}};assert.equal(measureEvent(p,'2026-09-20').outcomes[0].change,null);});
test('known missing daily sessions are not silently skipped',()=>{const p=parseStudyBars(payload,'NVO.US','1d','2026-09-24T08:00:00Z');p.expectedDates=['2026-09-21','2026-09-22','2026-09-23'];p.bars=p.bars.filter(b=>b.date!=='2026-09-22');assert.equal(measureEvent(p,'2026-09-20').outcomes[0].status,'窗口内日线缺失，暂不计算');assert.equal(measureEvent(p,'2026-09-21').status,'观察起点日线缺失');});
test('test case imports are idempotent, observation-only, and retain new retrieval time',()=>{const store=openStore(':memory:'),r=openResearch(store,{seed:false,clock:()=> '2026-09-24T10:00:00Z'}),t={id:'recent-test-one',origin:'recent-data-test',batchId:'one',inputHash:'abc',title:'New event',summary:'Review event',firstSeen:'2026-09-24T09:00:00Z',chain:[{id:'fact'},{id:'impact'},{id:'value'}],hypothesis:{action:'observe',invalidation:'Not supported'},companies:[{symbol:'BA.US',note:'Direct company'}],evidence:[{url:'https://example.org/press',claim:'Test-only fact',verification:'primary',stance:'supports',step:'fact'}]};try{const made=r.importTestCase(t);assert.equal(made.firstSeen,t.firstSeen);assert.equal(made.createdAt,'2026-09-24T10:00:00Z');assert.equal(r.importTestCase(t).version,1);assert.equal(r.history(t.id).length,1);assert.throws(()=>r.importTestCase({...t,inputHash:'changed'}),/不能覆盖/);assert.throws(()=>r.importTestCase({...t,id:'recent-test-two',hypothesis:{...t.hypothesis,action:'buy'}}),/只允许观察/);}finally{store.close();}});
